58	// residentGitKey names a read: the root, the commit it was made at (empty for a read by object
59	// id), the shallow state of the repository and the exact command. A root whose Git directory
60	// is not a plain .git directory is not memoized: its shallow state is not read here. The key
61	// also holds the digest of the effective Git configuration of the root.
62	func residentGitKey(root, head, config string, args []string) (string, bool) {
63		if config == "" {
64			// The effective Git configuration could not be read: nothing is memoized.
65			return "", false
66		}
67		gitDir := filepath.Join(root, ".git")
68		info, err := os.Lstat(gitDir)
69		if err != nil || !info.IsDir() {
70			return "", false
71		}
72		// The shallow file and the repository config are small: their content, not a timestamp,
73		// is part of the key.
74		digestOf := func(name string) string {
75			raw, err := os.ReadFile(filepath.Join(gitDir, name))
76			if err != nil {
77				return "-"
78			}
79			sum := sha256.Sum256(raw)
80			return hex.EncodeToString(sum[:8])
81		}
82		shallow := digestOf("shallow")
83		// config is the digest of the effective Git configuration of the root (system, global, user,
84		// repository, worktree and command-line scopes, includes followed): any of them can change
85		// what a read answers (log.follow, for one), and the digest is taken once per operation.
86		return strings.Join([]string{filepath.Clean(root), head, shallow, config, strings.Join(args, "\x00")}, "\x01"), true
87	}
